using Xunit;
using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using RaceDay.Contracts;
namespace RaceDay.Api.Tests;
public sealed class ApiBehaviourTests {
    private static async Task Login(HttpClient c,string email,string password){var r=await c.PostAsJsonAsync("/api/auth/login",new LoginRequest(email,password));Assert.Equal(HttpStatusCode.OK,r.StatusCode);}
    [Fact]public async Task Events_Can_Be_Browsed_Without_Login(){using var f=new TestAppFactory();using var c=f.NewClient();var r=await c.GetAsync("/api/events");Assert.Equal(HttpStatusCode.OK,r.StatusCode);Assert.True((await r.Content.ReadFromJsonAsync<List<EventDto>>())!.Count>=3);}
    [Fact]public async Task Anonymous_Cannot_Create_An_Event(){using var f=new TestAppFactory();using var c=f.NewClient();var r=await c.PostAsJsonAsync("/api/events",NewEvent());Assert.Equal(HttpStatusCode.Unauthorized,r.StatusCode);}
    [Fact]public async Task Anonymous_Cannot_Access_Profile(){using var f=new TestAppFactory();using var c=f.NewClient();Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/profile")).StatusCode);}
    [Fact]public async Task Registration_Rejects_Invalid_Role(){using var f=new TestAppFactory();using var c=f.NewClient();var r=await c.PostAsJsonAsync("/api/auth/register",new RegisterRequest("Test User","x@sample.org","Strong123!","Admin","0820000000","Durban"));Assert.Equal(HttpStatusCode.BadRequest,r.StatusCode);}
    [Fact]public async Task Registration_Rejects_Duplicate_Email(){using var f=new TestAppFactory();using var c=f.NewClient();var r=await c.PostAsJsonAsync("/api/auth/register",new RegisterRequest("Test User","runner@raceday.test","Strong123!","Participant","0820000000","Durban"));Assert.Equal(HttpStatusCode.Conflict,r.StatusCode);}
    [Fact]public async Task Registration_And_Login_Work(){using var f=new TestAppFactory();using var c=f.NewClient();var reg=await c.PostAsJsonAsync("/api/auth/register",new RegisterRequest("New Athlete","new@sample.org","Strong123!","Participant","0820000000","Durban"));Assert.Equal(HttpStatusCode.Created,reg.StatusCode);await Login(c,"new@sample.org","Strong123!");Assert.Equal(HttpStatusCode.OK,(await c.GetAsync("/api/profile")).StatusCode);}
    [Fact]public async Task Registration_Rejects_Password_Without_All_Character_Classes(){using var f=new TestAppFactory();using var c=f.NewClient();var r=await c.PostAsJsonAsync("/api/auth/register",new RegisterRequest("Weak User","weak@sample.org","Runner123","Participant","0820000000","Durban"));Assert.Equal(HttpStatusCode.BadRequest,r.StatusCode);}
    [Fact]public async Task Incorrect_Password_Is_Rejected(){using var f=new TestAppFactory();using var c=f.NewClient();var r=await c.PostAsJsonAsync("/api/auth/login",new LoginRequest("runner@raceday.test","wrong-password"));Assert.Equal(HttpStatusCode.Unauthorized,r.StatusCode);}
    [Fact]public async Task Participant_Cannot_Create_Event(){using var f=new TestAppFactory();using var c=f.NewClient();await Login(c,"runner@raceday.test","DemoRunner123!");Assert.Equal(HttpStatusCode.Forbidden,(await c.PostAsJsonAsync("/api/events",NewEvent())).StatusCode);}
    [Fact]public async Task Organiser_Can_Create_And_Edit_Event(){using var f=new TestAppFactory();using var c=f.NewClient();await Login(c,"organiser@raceday.test","DemoOrg123!");var create=await c.PostAsJsonAsync("/api/events",NewEvent());Assert.Equal(HttpStatusCode.Created,create.StatusCode);var dto=await create.Content.ReadFromJsonAsync<EventDto>();Assert.NotNull(dto);var update=await c.PutAsJsonAsync($"/api/events/{dto.Id}",NewEvent() with {Name="Updated Test Race"});Assert.Equal(HttpStatusCode.NoContent,update.StatusCode);var e=await c.GetFromJsonAsync<EventDto>($"/api/events/{dto.Id}");Assert.Equal("Updated Test Race",e!.Name);}
    [Fact]public async Task Participant_Cannot_Delete_Event(){using var f=new TestAppFactory();using var c=f.NewClient();await Login(c,"runner@raceday.test","DemoRunner123!");Assert.Equal(HttpStatusCode.Forbidden,(await c.DeleteAsync("/api/events/1")).StatusCode);}
    [Fact]public async Task Participant_Can_Enter_And_View_Race(){using var f=new TestAppFactory();using var c=f.NewClient();await Login(c,"runner2@raceday.test","DemoRunner123!");var r=await c.PostAsJsonAsync("/api/enrolments",new EnrolRequest(2,2));Assert.Equal(HttpStatusCode.Created,r.StatusCode);var entries=await c.GetFromJsonAsync<List<EnrolmentDto>>("/api/enrolments/mine");Assert.Contains(entries!,x=>x.EventId==2);}
    [Fact]public async Task Duplicate_Enrolment_Is_Blocked(){using var f=new TestAppFactory();using var c=f.NewClient();await Login(c,"runner@raceday.test","DemoRunner123!");var r=await c.PostAsJsonAsync("/api/enrolments",new EnrolRequest(2,2));Assert.Equal(HttpStatusCode.Conflict,r.StatusCode);}
    [Fact]public async Task An_Organiser_Cannot_Enrol_As_Participant(){using var f=new TestAppFactory();using var c=f.NewClient();await Login(c,"organiser@raceday.test","DemoOrg123!");var r=await c.PostAsJsonAsync("/api/enrolments",new EnrolRequest(2,2));Assert.Equal(HttpStatusCode.Forbidden,r.StatusCode);}
    [Fact]public async Task Cannot_Enter_Another_Event_Category(){using var f=new TestAppFactory();using var c=f.NewClient();await Login(c,"runner2@raceday.test","DemoRunner123!");var r=await c.PostAsJsonAsync("/api/enrolments",new EnrolRequest(2,4));Assert.Equal(HttpStatusCode.BadRequest,r.StatusCode);}
    [Fact]public async Task Organiser_Cannot_Publish_Future_Results(){using var f=new TestAppFactory();using var c=f.NewClient();await Login(c,"organiser@raceday.test","DemoOrg123!");var r=await c.PostAsJsonAsync("/api/results",new ResultWriteRequest(2,3600,1,30));Assert.Equal(HttpStatusCode.Conflict,r.StatusCode);}
    [Fact]public async Task Organiser_Can_Publish_Past_Results(){using var f=new TestAppFactory();using var c=f.NewClient();await Login(c,"organiser@raceday.test","DemoOrg123!");var r=await c.PostAsJsonAsync("/api/results",new ResultWriteRequest(1,3300,50,312));Assert.Equal(HttpStatusCode.OK,r.StatusCode);}
    [Fact]public async Task Participant_Can_See_Own_Results(){using var f=new TestAppFactory();using var c=f.NewClient();await Login(c,"runner@raceday.test","DemoRunner123!");var r=await c.GetFromJsonAsync<List<ResultDto>>("/api/results/mine");Assert.Contains(r!,x=>x.EventName=="Heritage Road Race");}
    [Fact]public async Task Logging_Out_Invalidates_Session(){using var f=new TestAppFactory();using var c=f.NewClient();await Login(c,"runner@raceday.test","DemoRunner123!");Assert.Equal(HttpStatusCode.NoContent,(await c.PostAsync("/api/auth/logout",null)).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/profile")).StatusCode);}
    [Fact]public async Task Organiser_Cannot_Manage_Another_Organisers_Event(){using var f=new TestAppFactory();using var c=f.NewClient();await Login(c,"organiser2@raceday.test","DemoOrg123!");Assert.Equal(HttpStatusCode.Forbidden,(await c.DeleteAsync("/api/events/2")).StatusCode);}
    [Fact]public async Task Unknown_Event_Returns_404(){using var f=new TestAppFactory();using var c=f.NewClient();Assert.Equal(HttpStatusCode.NotFound,(await c.GetAsync("/api/events/99999")).StatusCode);}
    private static EventWriteRequest NewEvent()=>new("Test Road Race","A community fun race",DateTime.UtcNow.AddDays(15),"Durban",10,"Run");
}
